    function startCountdown(cutoffISO) {
        const timerEl = document.getElementById('countdown-timer');
        if (!timerEl || !cutoffISO) return;
        const update = () => {
            const now = new Date().getTime();
            const distance = new Date(cutoffISO).getTime() - now;
            if (distance < 0) {
                timerEl.innerHTML = "<div style='background:#fee2e2; padding:10px; border-radius:12px; border:1px solid #ef4444; margin-bottom:1.5rem; text-align:center;'><span style='color:#ef4444; font-weight:900;'>⌛ DÉLAI DE COMMANDE DÉPASSÉ</span></div>";
                const addBtn = document.getElementById('add-to-cart-btn');
                if (addBtn) { addBtn.disabled = true; addBtn.textContent = "Indisponible"; }
                return;
            }
            const days = Math.floor(distance / (1000 * 60 * 60 * 24));
            const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((distance % (1000 * 60)) / 1000);
            timerEl.innerHTML = `<div style="display:flex; gap:10px; align-items:center; justify-content:center; background:#fff1f2; padding:10px; border-radius:12px; border:1px solid #fecdd3; margin-bottom:1.5rem;"><span style="font-size:1.2rem;">⏳</span><div style="text-align:left;"><p style="font-size:0.7rem; fonnt-weight:900; color:#e11d48; margin:0; text-transform:uppercase; letter-spacing:0.5px;">Temps restant pour commander</p><p style="font-family:monospace; font-size:1.1rem; font-weight:900; color:#1a1a1a; margin:0;">${days}j ${hours}h ${minutes}m ${seconds}s</p></div></div>`;
        };
        update(); setInterval(update, 1000);
    }

