                    </div>
                    <div>
                        <h3 className="font-black text-gray-800 text-lg leading-tight pr-24">{clientName}</h3>
                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">ID: {demande.id.substring(0, 8)}</p>
