        page.drawText(`${remaining.toFixed(2)} €`, { x: 470, y: totalsY, size: 12, font: fontBold, color: gold });
    }

    // === MENTIONS PAIEMENT ===
    y -= (depositAmount > 0 ? 80 : 60);
